class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseAge(raw) {
  const n = Number(raw);
  if (raw.trim() === "") throw new ValidationError("age", "Введите возраст");
  if (Number.isNaN(n)) throw new ValidationError("age", "Нужно число");
  if (n < 0 || n > 120) throw new ValidationError("age", "Вне диапазона");
  return n;
}

function run(value) {
  try {
    console.log("Возраст:", parseAge(value));
  } catch (e) {
    if (e instanceof ValidationError) {
      console.log(`Ошибка в ${e.field}: ${e.message}`);
    } else {
      throw e;
    }
  } finally {
    console.log("Проверка завершена");
  }
}

run("");
run("abc");
